// CollectionsOverdueSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/mda4/reports/collections/overdue/list/CollectionsOverdueSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import CollectionsOverdueActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const CollectionsOverdueSchema = {
  entity: 'simukopa_collections_overdue',
  label: 'Overdue Analysis',
  description: '',
  apiBase: apiRoutes.collectionsoverdue?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: CollectionsOverdueActions,

  groupBy: 'month',
  groupLabel: 'Month',
  groupByOptions: [{ key: 'month', label: 'Month' }, { key: 'day', label: 'Day' }, { key: 'year', label: 'Year' }],

  fields: [
    { key: 'due', label: 'Installments Due', from: 'loan_installments' },
    { key: 'expected', label: 'Amount Due', from: 'loan_installments.total_amount', type: 'money' },
    { key: 'paid', label: 'Paid', from: 'loan_installments.paid_amount', type: 'money' },
    { key: 'unpaid', label: 'Unpaid', from: 'loan_installments.balance_amount', type: 'money' },
    { key: 'late', label: 'Overdue Installments', from: 'loan_installments' },
    { key: 'late_amount', label: 'Overdue Amount', from: 'loan_installments.balance_amount', type: 'money' },
    { key: 'penalties', label: 'Penalties Charged', from: 'loan_installments.penalty_amount', type: 'money' },
    { key: 'rate', label: 'Collected %', calc: 'round(paid / expected * 100)' },
    { key: 'chg', label: 'Overdue vs Previous', calc: 'change(late_amount)' },
  ],

  remarks: [
    { if: 'due == 0', tone: 'neutral', title: 'Nothing due', say: 'No installments fell due in {label}.' },
    { if: 'rate !== null && rate < 70', tone: 'bad', title: 'Weak collection', say: 'Only {rate}% of the {expected} due in {label} was collected, and {late_amount} is overdue.' },
    { if: 'late > 0', tone: 'watch', title: 'Overdue', say: '{late} installments worth {late_amount} are overdue for {label}.' },
    { if: 'true', tone: 'good', title: 'On track', say: '{rate}% of the {expected} due in {label} was collected.' },
  ],

  headline: '{label}: {due} installments due, {rate}% collected, {late_amount} overdue.',
};
